#!/bin/bash
# zynthian package script for the @@NAME@@ LV2 plugin (zynthian-packages: @@CATEGORY@@/@@PACKAGE@@).
# Installs the bundle of the latest release built by the plugin's GitHub CI (x86_64 or arm64). webconf offers an
# update when a newer v* release is tagged: new versions don't need changes here.
# Generated by the zynthian-lv2-plugin skill.

REPO="@@SYMBOL@@"
GITHUB="@@GITHUB@@"
PLUGIN_URI="@@URI@@"

DIRNAME="$REPO.lv2"
REPO_URL="https://github.com/$GITHUB.git"
DST_DIR="$ZYNTHIAN_PLUGINS_DIR/lv2"

case "$MACHINE_HW_NAME" in
    aarch64) CPU_ARCH="arm64" ;;
    x86_64) CPU_ARCH="x86_64" ;;
    *) CPU_ARCH="" ;;
esac
FILENAME="$REPO-lv2-$CPU_ARCH.tar.gz"
DOWNLOAD_URL="https://github.com/$GITHUB/releases/latest/download/$FILENAME"

do_install() {
    set -ex
    [ -n "$CPU_ARCH" ] || { echo "unsupported architecture: $MACHINE_HW_NAME"; exit 1; }
    mkdir -p "$DST_DIR"
    cd "$DST_DIR"
    wget -q -O "$FILENAME" "$DOWNLOAD_URL"
    rm -rf "$DIRNAME"
    tar xzf "$FILENAME"
    rm -f "$FILENAME"
    set +x
    $ZYNTHIAN_SYS_DIR/sbin/zynengine_tool.py ENABLE "$PLUGIN_URI"
    echo "installed"
}

do_uninstall() {
    if [[ $(is_installed) == "installed" ]]; then
        rm -rf "$DST_DIR/$DIRNAME"
        echo "uninstalled"
    else
        echo "not installed"
    fi
}

is_installed() {
    if [[ -d "$DST_DIR/$DIRNAME" ]]; then
        echo "installed"
    else
        echo "not installed"
    fi
}

git_repo() {
    echo $REPO_URL
}

# Version = newest v* release tag (webconf offers an update when it changes)
git_version() {
    git ls-remote --tags --refs "$REPO_URL" 'v*' | awk -F/ '{ print $3 }' | sort -V | tail -1
}

if [[ "$1" == "install" ]]; then
    do_install
elif [[ "$1" == "uninstall" ]]; then
    do_uninstall
elif [[ "$1" == "installed" ]]; then
    echo $(is_installed)
elif [[ "$1" == "git_version" ]]; then
    echo $(git_version)
elif [[ "$1" == "git_repo" ]]; then
    echo $(git_repo)
fi
